python -m py_compile /app/jump_analyzer.py && python -c "import ast
p='/app/jump_analyzer.py'; tree=ast.parse(open(p,encoding='utf-8').read()); allowed={'cv2','numpy'}
imports=[]
for n in ast.walk(tree):
 if isinstance(n,ast.Import): imports += [x.name.split('.')[0] for x in n.names]
 if isinstance(n,ast.ImportFrom) and n.module: imports.append(n.module.split('.')[0])
assert set(imports) <= allowed, imports
print('{\"syntax\":true,\"imports_allowed\":true}')"
